                continue
            color = grid[r][c]
            comp[r][c] = next_id
            stack = [(r, c)]
            while stack:
                y, x = stack.pop()
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                        grid[ny][nx] == color and comp[ny][nx] == -1):
                        comp[ny][nx] = next_id
                        stack.append((ny, nx))
            next_id += 1

    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not pts:
        return [row[:] for row in grid]
    r0 = min(r for r, c in pts)
    r1 = max(r for r, c in pts)
